def generate(seed):
    r = random.Random(seed)
    while True:
        nb = r.choice([4, 4, 5])
        L = r.randint(4, 10)
        if L > (1 << nb) - 1:
            continue
        cur = ''.join(r.choice('01') for _ in range(nb))
        path = [cur]
        seen = {cur}
        ok = True
        for _ in range(L):
            nxt = [cur[:i] + ('1' if cur[i] == '0' else '0') + cur[i + 1:] for i in range(nb)]
            nxt = [q for q in nxt if q not in seen]
            if not nxt:
                ok = False
                break
            cur = r.choice(nxt)
            seen.add(cur)
            path.append(cur)
        if ok:
            return path[0] + ' ' + path[-1] + ' ' + str(L)

