def solve(clue):
    a, b, n = clue.split()
    n = int(n)
    L = len(a)
    path = [a]
    seen = {a}
    def ham(u, v):
        return sum(1 for p, q in zip(u, v) if p != q)
    def dfs(cur, left):
        if left == 0:
            return cur == b
        d = ham(cur, b)
        if d > left or (left - d) % 2:
            return False
        for i in range(L):
            nx = cur[:i] + ('1' if cur[i] == '0' else '0') + cur[i + 1:]
            if nx in seen:
                continue
            seen.add(nx)
            path.append(nx)
            if dfs(nx, left - 1):
                return True
            seen.discard(nx)
            path.pop()
        return False
    dfs(a, n)
    return ' '.join(path)

